begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select lives_ok($q$select private.validate_schedule_document('{"meta":{"timing":{"mode":"flexible","between":"backward"}},"rows":[{"timeIn":"11:00 PM","timeInDay":-1,"dur":"02:00","fixedOut":true,"fixedOutTime":"1:00 AM","fixedOutDay":0}]}',1)$q$,'Backward overnight document is accepted');
select lives_ok($q$select private.validate_schedule_document('{"meta":{"timing":{"mode":"flexible","between":"forward"}},"rows":[]}',1)$q$,'Forward settings are accepted');
select lives_ok($q$select private.validate_schedule_document('{"meta":{},"rows":[]}',1)$q$,'Old documents remain accepted');
select throws_ok($q$select private.validate_schedule_document('{"meta":{"timing":null},"rows":[]}',1)$q$,'PT400',null,'Null timing is rejected');
select throws_ok($q$select private.validate_schedule_document('{"meta":{"timing":{"mode":"flexible"}},"rows":[]}',1)$q$,'PT400',null,'Incomplete settings are rejected');
select throws_ok($q$select private.validate_schedule_document('{"meta":{"timing":{"mode":"flexible","between":"random"}},"rows":[]}',1)$q$,'PT400',null,'Invalid planning direction is rejected');
select throws_ok($q$select private.validate_schedule_document('{"meta":{"timing":{"mode":"flexible","between":"forward","x":1}},"rows":[]}',1)$q$,'PT400',null,'Unknown settings are rejected');
select throws_ok($q$select private.validate_schedule_document('{"meta":{},"rows":[{"timeInDay":0.5}]}',1)$q$,'PT400',null,'Fractional day is rejected');
select throws_ok($q$select private.validate_schedule_document('{"meta":{},"rows":[{"fixedOutDay":"1"}]}',1)$q$,'PT400',null,'String day is rejected');
select throws_ok($q$select private.validate_schedule_document('{"meta":{},"rows":[{"fixedOutDay":1000001}]}',1)$q$,'PT400',null,'Day overflow is rejected');
select throws_ok($q$select private.validate_schedule_document('{"meta":{},"rows":[{"timeIn":"12:99 PM"}]}',1)$q$,'PT400',null,'Bad clock remains rejected');
select is(private.client_projection('{"meta":{},"rows":[{"action":"Shoot","timeInDay":-1,"fixedOutDay":1,"contactEmail":"private@example.test"}]}'::jsonb)#>>'{rows,0,timeInDay}','-1','Client view retains start date offset');
select is(private.client_projection('{"meta":{},"rows":[{"action":"Shoot","timeInDay":-1,"fixedOutDay":1,"contactEmail":"private@example.test"}]}'::jsonb)#>>'{rows,0,fixedOutDay}','1','Client view retains finish date offset');
select ok(not (private.client_projection('{"meta":{},"rows":[{"action":"Shoot","contactEmail":"private@example.test"}]}'::jsonb)#>'{rows,0}' ? 'contactEmail'),'Client view still excludes contact information');
select * from finish();
rollback;
